const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_xDistBuf;
float4 amzSample_xDistBuf(float2 uv) { return float4(amzt_xDistBuf.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
